func sizedAgents(t *testing.T, width int, u agentusage.Usage, c statusClock) Model {
	t.Helper()
	m := withSessions(t, "/p/a.jsonl")
	m = feed(t, m, testutil.Resize(width, 20))
	m, _ = opened(t, m, "right")
	m.clock = c
	return answer(t, m, u)
