func TestSortKeepsEveryRowsState(t *testing.T) {
	tn := time.Now()
	u := activityUsage(tn)
	u.Agents[1].LastActivity = tn.Add(-20 * time.Minute) // unfinished and quiet: idle
	m := sizedAgents(t, 120, u, statusClock{now: tn, alive: true})
