231	// dimWhen is Rule 122's colour discipline: a zero or a placeholder is dim,
232	// anything else keeps the default colour.
233	func dimWhen(dim bool) lipgloss.Style {
234		if dim {
235			return theme.DimStyle
236		}
237		return lipgloss.NewStyle()
238	}
