243	
244	// idCell is the ID column: the short ID of a sub-agent, a dash for the
245	// orchestrator, which has none.
246	func idCell(r agentRow) string {
247		switch {
248		case r.Main:
249			return noValue
250		case r.shortID == "":
251			return unknownID
252		}
253		return r.shortID
254	}
