273	func modelsCell(r agentRow) string {
274		if len(r.Models) == 0 {
275			return noModel
276		}
277		return strings.Join(r.Models, ", ")
278	}
279	
280	// outCell is the output count. A sub-agent still being written is a floor and
281	// says so; the orchestrator never does, its transcript is the one being read.
282	func outCell(r agentRow) string {
283		out := formatTokens(r.Tokens.Output)
284		if !r.Main && r.PartialOutput() {
285			return partialMark + out
286		}
287		return out
288	}
289	
290	// formatTokens renders a count compactly, floored to one decimal: 1099 is
291	// "1.0k", never "1.1k". From 100 of a unit up the decimal is dropped.
292	func formatTokens(n int64) string {
293		units := []struct {
294			size   int64
295			suffix string
296		}{
297			{1_000_000_000_000, "T"}, {1_000_000_000, "B"}, {1_000_000, "M"}, {1_000, "k"},
298		}
299		for _, u := range units {
300			if n < u.size {
301				continue
302			}
303			tenths := n / (u.size / 10) // divide first: n*10 would overflow
304			if tenths >= 1000 {
305				return fmt.Sprintf("%d%s", tenths/10, u.suffix)
306			}
307			return fmt.Sprintf("%d.%d%s", tenths/10, tenths%10, u.suffix)
308		}
309		return fmt.Sprintf("%d", n)
310	}
311	
312	// formatDuration renders a duration compactly; known is false when the
313	// transcript carried no timestamp.
314	func formatDuration(d time.Duration, known bool) string {
315		if !known {
316			return noValue
317		}
318		switch {
319		case d < time.Minute:
320			return fmt.Sprintf("%ds", max(int(d/time.Second), 0))
321		case d < time.Hour:
322			return fmt.Sprintf("%dm%02ds", int(d/time.Minute), int(d%time.Minute/time.Second))
323		case d < 24*time.Hour:
324			return fmt.Sprintf("%dh%02dm", int(d/time.Hour), int(d%time.Hour/time.Minute))
325		case d < 100*24*time.Hour:
326			return fmt.Sprintf("%dd%02dh", int(d/(24*time.Hour)), int(d%(24*time.Hour)/time.Hour))
327		}
328		return ">99d"
329	}

