	m, quiet := quietPoll(t)
	tn := time.Now()
	m.clock = statusClock{now: tn, alive: true}
	m = m.withUsage(agentusage.Usage{Agents: []agentusage.Agent{
		stamped(orchestrator(5, 0), 1, tn.Add(-time.Hour), tn),
