// lineOf is the last line of view that mentions role.
func lineOf(t *testing.T, view, role string) string {
	t.Helper()
	var line string
	for _, l := range strings.Split(view, "\\n") {
		if strings.Contains(l, role) {
			line = l
		}
	}
	if line == "" {
